package org.example

import dev.openfeature.contrib.providers.flagd.Config
import dev.openfeature.contrib.providers.flagd.FlagdOptions
import dev.openfeature.contrib.providers.flagd.FlagdProvider
import dev.openfeature.contrib.providers.flagd.resolver.process.storage.connector.QueuePayload
import dev.openfeature.contrib.providers.flagd.resolver.process.storage.connector.QueuePayloadType
import dev.openfeature.contrib.providers.flagd.resolver.process.storage.connector.QueueSource
import dev.openfeature.sdk.EventDetails
import dev.openfeature.sdk.EventProvider
import dev.openfeature.sdk.OpenFeatureAPI
import java.time.Duration
import java.util.concurrent.BlockingQueue
import java.util.concurrent.LinkedBlockingQueue
import java.util.function.Consumer

open class OpenFeatureConfiguration {
    private val oneValueQueueSource = OneValueQueueSource()
    private val flagdProvider = flagdProvider(oneValueQueueSource)

    open fun createAndSubscribeOpenFeatureAPI(
        handler: Consumer<EventDetails>
    ): OpenFeatureAPI {
        val openFeatureAPI = OpenFeatureAPI.createIsolated()
        openFeatureAPI.setProviderAndWait(flagdProvider)
        openFeatureAPI.client.onProviderReady(handler)
        return openFeatureAPI
    }

    fun flagdProvider(
        queueSource: QueueSource,
    ): EventProvider {
        return FlagdProvider(
            FlagdOptions.builder()
                .resolverType(Config.Resolver.IN_PROCESS)
                .customConnector(queueSource)
                .deadline(Duration.ofMillis(10000).toMillis().toInt())
                .build()
        )
    }
}

class OneValueQueueSource : QueueSource {
    private val queue: BlockingQueue<QueuePayload> = LinkedBlockingQueue(1)

    override fun init() {
        queue.put(QueuePayload(QueuePayloadType.DATA, """{"flags": {"flag1": {"state": "ENABLED"}}}"""))
    }

    override fun getStreamQueue(): BlockingQueue<QueuePayload> {
        return queue
    }

    override fun shutdown() {
    }

}